#!/bin/sh
set -eu
test "$#" -eq 1 || { echo "usage: ROLLBACK.sh TARGET_COPY_DIRECTORY" >&2; exit 2; }
root=$1
test -d "$root" || { echo "target directory missing" >&2; exit 2; }
mkdir -p "$root/UnityProject/Assets/Scripts/Game/WitchTrials.Game/WitchTrials.Views"
base64 -d > "$root/UnityProject/Assets/Scripts/Game/WitchTrials.Game/WitchTrials.Views/LocalizeImage.cs" <<'BASELINE_0'

BASELINE_0
mkdir -p "$root/UnityProject/Assets/Scripts/Runtime"
base64 -d > "$root/UnityProject/Assets/Scripts/Runtime/ManosabaBoot.cs" <<'BASELINE_1'

BASELINE_1
